function merge(iv) {
  iv.sort((a, b) => a[0] - b[0]);
  const out = [];
  for (const [s, e] of iv) {
    const last = out[out.length - 1];
    if (last && s <= last[1]) last[1] = Math.max(last[1], e);
    else out.push([s, e]);
  }
  return out;
}
console.log(JSON.stringify(merge([[8, 10], [1, 3], [2, 6], [15, 18]])));

function count(nums, k) {
  const seen = new Map([[0, 1]]);
  let sum = 0, res = 0;
  for (const x of nums) {
    sum += x;
    res += seen.get(sum - k) ?? 0;
    seen.set(sum, (seen.get(sum) ?? 0) + 1);
  }
  return res;
}
console.log(count([1, 2, 3, -3, 3], 3));

function f(n) {
  if (n <= 1) return 1;
  return f(n - 1) + f(n - 1);
}

